// Test harness for trusted generated bytes, never an upload/runtime adapter.
import {fork} from 'node:child_process'
import {randomUUID} from 'node:crypto'
import {fileURLToPath} from 'node:url'
import {dirname} from 'node:path'
import {verifyPptxCandidate} from '../../scripts/prepare-pptx-runtime-candidate.mjs'
import {validatePptxOutline} from '../../worker/src/sandbox/pptx-outline-schema.ts'
const ENTRY=fileURLToPath(new URL('./pptx-candidate-entry.mjs',import.meta.url))
const exact=(value,keys)=>value&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).sort().join(',')===[...keys].sort().join(',')
const invalid=()=>new Error('PPTX_FIXTURE_INVALID_REPLY')
function openReply(value){
 if(!exact(value,['count','size'])||!Number.isSafeInteger(value.count)||value.count<1||value.count>1500||!exact(value.size,['cx','cy'])||Object.values(value.size).some(n=>!Number.isSafeInteger(n)||n<1||n>2147483647))throw invalid()
 return structuredClone(value)
}
export async function openGeneratedPptxCandidateFixture({directory,contentDigest,bytes,unsafeGeneratedFixtureOnly}){
 if(process.env.NODE_ENV!=='test'||unsafeGeneratedFixtureOnly!==true)throw new Error('PPTX_FIXTURE_ONLY')
 if(!(bytes instanceof Uint8Array)||bytes.byteLength<1||bytes.byteLength>1024*1024)throw new Error('PPTX_FIXTURE_INPUT_LIMIT')
 const copied=Uint8Array.from(bytes),binding=Object.freeze({fileId:randomUUID(),revision:randomUUID()})
 const candidateDirectory=directory,expectedDigest=contentDigest
 await verifyPptxCandidate(candidateDirectory,expectedDigest)
 if(process.env.NODE_ENV!=='test')throw new Error('PPTX_FIXTURE_ONLY')
 const child=fork(ENTRY,[candidateDirectory,expectedDigest],{
  execPath:process.execPath,execArgv:[],cwd:dirname(ENTRY),serialization:'advanced',
  env:{NODE_ENV:'test',DYOFFICE_GENERATED_PPTX_FIXTURE:'1'},
  stdio:['ignore','pipe','pipe','ipc'],
 })
 let pending,closed=false,exited=false,nextId=1,requests=0,cleanupPromise
 let exitResolve
 const exit=new Promise(resolve=>{exitResolve=resolve})
 async function cleanup(){
  if(cleanupPromise)return cleanupPromise
  closed=true;clearTimeout(deadline)
  cleanupPromise=(async()=>{
   if(!exited)child.kill('SIGKILL')
   let timer
   try{await Promise.race([exit,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error('PPTX_FIXTURE_CLEANUP_UNCONFIRMED')),1000)})])}
   finally{clearTimeout(timer);child.stdout?.destroy();child.stderr?.destroy();if(child.connected)child.disconnect()}
  })()
  return cleanupPromise
 }
 function fatal(error){
  closed=true
  if(pending){const current=pending;pending=undefined;current.reject(error)}
  void cleanup().catch(()=>{})
 }
 const deadline=setTimeout(()=>fatal(new Error('PPTX_FIXTURE_TIMEOUT')),10000)
 for(const stream of [child.stdout,child.stderr]){
  let total=0
  stream.on('data',chunk=>{total+=chunk.length;if(total>64*1024)fatal(new Error('PPTX_FIXTURE_OUTPUT_LIMIT'))})
  stream.on('error',()=>fatal(new Error('PPTX_FIXTURE_PIPE')))
 }
 child.on('error',error=>fatal(error))
 child.on('exit',()=>{exited=true;exitResolve();if(pending)fatal(new Error('PPTX_FIXTURE_EARLY_EXIT'));else{closed=true;clearTimeout(deadline)}})
 child.on('disconnect',()=>{if(pending)fatal(new Error('PPTX_FIXTURE_DISCONNECT'))})
 child.on('message',raw=>{
  try{
   if(!pending||!raw||JSON.stringify(raw).length>64*1024||raw.id!==pending.id)throw invalid()
   const current=pending
   if(raw.ok===false){
    if(!exact(raw,['id','ok','error'])||typeof raw.error!=='string'||raw.error.length>256)throw invalid()
    throw new Error(raw.error)
   }
   if(raw.ok!==true||!exact(raw,['id','ok','result']))throw invalid()
   const result=current.method==='open'?openReply(raw.result):current.method==='outline'?validatePptxOutline(raw.result):raw.result===true?true:(()=>{throw invalid()})()
   pending=undefined;current.resolve(result)
  }catch(error){fatal(error)}
 })
 async function call(method,fields={}){
  if(process.env.NODE_ENV!=='test'||closed||exited)throw new Error('PPTX_FIXTURE_CLOSED')
  if(pending||++requests>8){const error=new Error('PPTX_FIXTURE_PENDING_LIMIT');fatal(error);await cleanup();throw error}
  const id=nextId++
  try{
   return await new Promise((resolve,reject)=>{
    pending={id,method,resolve,reject}
    child.send({id,m:method,...fields},error=>{if(error&&pending?.id===id)fatal(error)})
   })
  }catch(error){await cleanup();throw error}
 }
 try{
  const opened=await call('open',{binding,bytes:copied})
  return Object.freeze({
   opened,
   async outline(expected=0,overrideBinding=binding){
    if(!Number.isSafeInteger(expected)||expected<0){await cleanup();throw new Error('PPTX_FIXTURE_GENERATION')}
    if(!exact(overrideBinding,['fileId','revision'])||Object.values(overrideBinding).some(v=>typeof v!=='string'||v.length<1||v.length>128)){await cleanup();throw new Error('PPTX_FIXTURE_BINDING')}
    const snapshot={fileId:overrideBinding.fileId,revision:overrideBinding.revision}
    return call('outline',{expected,binding:snapshot})
   },
   async close(){const acknowledged=await call('close',{binding});await cleanup();return acknowledged},
   dispose:cleanup,
  })
 }catch(error){await cleanup();throw error}
}
